function voicePlanToManuscript(plan?:VoicePlan){
  if(!plan)return "";
  if(plan.manuscript?.trim()&&plan.manuscriptFormatVersion===3)return plan.manuscript.trim();
  const sectionForPage=(page:number)=>plan.sections.find(section=>page>=section.startPage&&page<=section.endPage);
  const chapters=[`课程主线\n${plan.courseThesis}`,"章节安排",...plan.sections.map((section,index)=>`${String(index+1).padStart(2,"0")}  ${section.title} · ${section.targetMinutes} 分钟\n${section.purpose}`)];
  const introduction=plan.manuscript?.trim()||chapters.join("\n\n");
  if(!plan.pages?.length)return introduction;
  const pages=plan.pages.map(page=>{const chapter=sectionForPage(page.page);return `第 ${String(page.page).padStart(2,"0")} 页 · ${page.teachingTask}${chapter?` · ${chapter.title}`:""}\n学习目标：${page.learningOutcome}\n画面重点：${page.visualFocus}\n口播衔接：${page.continuity}\n建议篇幅：约 ${page.targetChars} 字`});
  return [introduction,"逐页口播安排",...pages].join("\n\n");
}
