function AutoGrowingTextarea({value,onChange,label}:{value:string;onChange:(value:string)=>void;label:string}){
  const textarea=useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(()=>{const element=textarea.current;if(!element)return;element.style.height="auto";element.style.height=`${element.scrollHeight}px`},[value]);
  return <textarea ref={textarea} rows={1} className="manuscript-editor" aria-label={label} value={value} onChange={event=>onChange(event.target.value)}/>;
}

function AudioSourceControl({slide,selected,recording,playing,current,positions,onSwitch,onToggle,onSeek}:{slide:Slide;selected:"ai"|"recording";recording:boolean;playing:boolean;current:"ai"|"recording";positions:Record<"ai"|"recording",number>;onSwitch:(source:"ai"|"recording")=>void;onToggle:(source:"ai"|"recording")=>void;onSeek:(source:"ai"|"recording",seconds:number)=>void}){
  const format=(seconds:number)=>`${Math.floor((Number.isFinite(seconds)?seconds:0)/60)}:${String(Math.floor((Number.isFinite(seconds)?seconds:0)%60)).padStart(2,"0")}`;
  const tracks=([{source:"ai" as const,label:"AI 配音",url:slide.aiAudioUrl,duration:slide.aiDurationSeconds||0},{source:"recording" as const,label:slide.recordingDenoised?"本人录音 · 已去噪":"本人录音",url:slide.recordingAudioUrl,duration:slide.recordingDurationSeconds||0}]);
  const track=tracks.find(item=>item.source===selected)!,isPlaying=playing&&current===track.source,position=Math.min(positions[track.source]||0,track.duration||0);
  return <div className="audio-source-control audio-source-simple"><div className="audio-source-tabs" role="radiogroup" aria-label="试听音频来源">{tracks.map(item=><button type="button" role="radio" aria-checked={item.source===selected} className={item.source===selected?"active":""} disabled={recording} onClick={()=>onSwitch(item.source)} key={item.source}>{item.label}</button>)}</div><div className={`audio-player-simple ${!track.url?"unavailable":""}`}><button className="audio-track-play" type="button" aria-label={`${isPlaying?"暂停":"播放"}${track.label}`} disabled={!track.url||recording} onClick={()=>onToggle(track.source)}>{isPlaying?<Pause size={14} weight="fill"/>:<Play size={14} weight="fill"/>}</button><span className="audio-simple-time">{format(position)}</span><input aria-label={`${track.label}播放进度`} type="range" min="0" max={track.duration||0} step="0.1" value={position} disabled={!track.url||recording} onChange={event=>onSeek(track.source,Number(event.target.value))} style={{"--track-progress":`${track.duration?position/track.duration*100:0}%`} as React.CSSProperties}/><span className="audio-simple-time">{track.url?format(track.duration):"—:—"}</span></div></div>
}

